// workbench-dev-team's hooks module, beside the command hooks in hooks.json.
// It builds on workbench-core's $.workbench noun (dependencies in plugin.json).
//
//   agent.spawn    one dispatch of an agent, in order:
//                  1. the dispatch gate: a main-session dispatch whose brief
//                     lacks a slot is refused, as hooks/agent-dispatch-gate.sh
//                     in workbench-core refuses it, and so is one whose brief
//                     cannot be checked
//                  2. the helper rule: a spawn Holmes makes, in any mode, runs
//                     on holmes-lens whatever type it named, and a fork or a
//                     teammate of his is refused
//                  3. the workspace check: a gated Watson Direct-mode brief
//                     whose Workdir: is a bare path, on a repo on main, master
//                     or trunk, is refused with an ask-for-a-branch reason
//                  4. routing: a dispatch of watson, holmes or lestrade runs the
//                     mode agent its token picks (bin/compose-agents.sh builds
//                     them), so the public names keep working
//                  5. model and effort from the plugin's /config rows (its
//                     options), and for holmes-local, holmes-index and
//                     lestrade-item the config line (fanout, lensModel) added
//                     to the prompt
//                  Each dev-team agent's type is kept by its agentId.
//   prompt.submit  the config line, as context, for the top-level loop of a
//                  `claude -p --agent` run of those three modes: the run
//                  bin/dispatch-agent.sh starts raises no agent.spawn
//   turn.step      applies the effort step 5 recorded, to that sub-agent's
//                  loop, and measures each dev-team request's working context
//                  against the budget, notifying the human once per run
//   turn.complete  deletes the run's scratch folder unless a child it spawned is
//                  still live, and resets its budget notice
//   session.end    deletes every scratch folder the mod still records, within
//                  the end's short time budget: a run whose last turn ended
//                  with a live child, and was never resumed, left one
//   session.start  registers /dev-team-runs and /dev-team-board, and restarts
//                  the panes' refresh timer when a reload finds a pane open
//   command.run    those two commands open their pane (mods/panes.tsx)
//   ui.render      draws the two panes, each read-only:
//                  - runs: the newest dispatch logs (mods/runs.ts), read again
//                    every 15 s while the pane is open
//                  - board: The Index's three lanes from bin/dispatch-tick.sh
//                    --board (mods/board.ts), fetched when the pane opens and
//                    then once per dispatch cadence at most, and the items the
//                    breaker escalated, from the log folder
//   tool.call      on Bash, Edit, Write and NotebookEdit, before the call:
//                  1. scratch: a dev-team agent's bare mktemp is pointed at a
//                     folder of its own under a scratch root (mods/scratch.ts)
//                  2. the commit guard (mods/commit-guard.ts), on every Bash
//                     line in every lane: a forced or deleting push, a merge by
//                     an agent or the pipeline, a sub-agent's commit or push,
//                     and a commit, push or merge the ask rules cannot see
//                  3. the commit subject check (mods/commit-subject.ts) on
//                     every commit the guard lets through
//                  4. the review guard (mods/review-guard.ts): a Holmes
//                     reviewer, or anything he spawned, writes only in scratch
//                  The guards read the line through $.workbench.parseShell,
//                  take the lane from $.workbench.callerLane and isUnattended,
//                  and refuse the call when they throw.
//                  On Agent, from the main session (mods/dispatch.ts): a Watson
//                  `Item ID: <n>` call runs bin/dispatch-agent.sh in its place
//                  and answers with the dispatcher's first line, and a dev-team
//                  call that did not ask for the foreground runs in the
//                  background. After the call ran: the gate's advisory hint on
//                  a complete brief that dictates method.
//   prompt.compose the dev-team session rules (mods/session-rules.ts) as one
//                  shared system-prompt section, in every lane but
//                  WORKBENCH_SKIP_WARMUP=1: after workbench-core's sections
//                  when this hook wraps core's, before them when core's wraps
//                  this one (withRules says why)
//   classic.SubagentStart
//                  the same rules as context at a sub-agent's start, as
//                  workbench-core gives its own, unless the agent is a fork,
//                  whose inherited prompt already holds the section, or its
//                  type leaves CLAUDE.md out
//
// The logic is pure and lives in mods/. Every hook that touches `$` lives in
// this file, because the engine follows `$` into no imported function, and a
// plugin registers each event once.
//
// The scheduled path never reaches agent.spawn: it starts the mode type
// directly (`claude -p --agent workbench-dev-team:watson-index`), and
// bin/dispatch-agent.sh passes the rows' model and effort as flags. The
// other hooks run in that process too.
//
// The /config rows reach this module as its options. Claude Code reloads the
// module when one changes, so `register` runs again with the new values.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer, TurnUsage } from 'claude-code'

import type { RunsView } from '../types'

import { BOARD_TIMEOUT_MS, EMPTY_BOARD, afterFetch, boardArgv, boardOutcome, cadenceMsOf, escalatedOf, isDue } from './mods/board'

import { budgetNotice, contextOf, isOverBudget } from './mods/budget'
import { commitVerdict } from './mods/commit-guard'
import type { ShellParse } from './mods/commit-guard'
import { subjectVerdict } from './mods/commit-subject'
import { DISPATCH_CONTEXT, dispatchDeny, dispatcherArgv, dispatchOutcome, dispatchResult, indexDispatchOf, isForcedBackground } from './mods/dispatch'
import type { Disk } from './mods/review-guard'
import { isReviewerType, judgeWrites, refusalOf, reviewBash, reviewEdit } from './mods/review-guard'
import { BOARD_PANE, RUNS_PANE, boardTree, runsTree } from './mods/panes'
import type { LogEnd } from './mods/runs'
import { LOG_DIR, RUNS_REFRESH_MS, endsOf, livePairsOf, markersOf, newestRuns, rowsOf, scanArgv } from './mods/runs'
import { RULES, isRulesLane, isRulesSubagent, withRules } from './mods/session-rules'
import { hasBareMktemp, hasLiveChild, isDeletable, pointMktemp, prefixOf, readsAsPointed, rootOf, sweepOf } from './mods/scratch'
import type { CallerLane } from './mods/spawn'
import {
  CONFIG_MODES,
  DEFAULT_BRANCHES,
  branchDeny,
  branchUnreadDeny,
  configLineOf,
  configTextOf,
  denyOf,
  familyOf,
  hintOf,
  isDevTeamType,
  isGated,
  isHolmesMode,
  knobsOf,
  lensSpawnOf,
  modeTypeOf,
  uncheckedDeny,
  withConfigLine,
  workdirOf,
} from './mods/spawn'

// Whether the dispatch gate judges a call made in the loop `agentId` names.
// The lane rejects while it is unknown; a gate then reads it as the main
// session, so the brief is still checked. orchestratorIsOn already fails toward
// on, and its .catch does the same.
async function gated($: EngineInterface, agentId: string | undefined): Promise<boolean> {
  const lane = await $.workbench.callerLane(agentId === undefined ? {} : { agentId }).catch(() => 'main' as const)
  const isOn = await $.workbench.orchestratorIsOn().catch(() => true)
  return isGated(lane, isOn)
}

// ── Whose run a loop is ──────────────────────────────────────────────────────

// A dev-team run, as the per-run state keys it: its agent type, and its agentId,
// or `run` for the top-level loop of a `claude -p --agent` run. Undefined for
// the main session and for every agent outside the dev-team.
type Run = { type: string; key: string }

async function runOf($: EngineInterface, agentId: string | undefined): Promise<Run | undefined> {
  if (agentId !== undefined) {
    const { value: type } = await $.state.get({ plugin: 'workbench-dev-team', key: 'agentType', id: agentId })
    return isDevTeamType(type) && type !== undefined ? { type, key: agentId } : undefined
  }
  if ((await $.workbench.callerLane({})) !== 'top-level-agent') return undefined
  const type = await $.env.get('CLAUDE_CODE_AGENT')
  return isDevTeamType(type) && type !== undefined ? { type, key: 'run' } : undefined
}

// The type of the loop a spawn happens in: the top-level `--agent` type, or
// none, for a main-loop spawn; the type the mod kept, or the one
// $.agent.list() gives, for a sub-agent's. Undefined when it cannot be told.
async function spawnerTypeOf($: EngineInterface, parentAgentId: string | undefined): Promise<string | undefined> {
  if (parentAgentId === undefined) return $.env.get('CLAUDE_CODE_AGENT').catch(() => undefined)
  const { value: kept } = await $.state.get({ plugin: 'workbench-dev-team', key: 'agentType', id: parentAgentId })
  if (kept !== undefined) return kept
  const agents = await $.agent.list().catch(() => undefined)
  return agents?.find(agent => agent.id === parentAgentId)?.type
}

// ── Scratch folders ──────────────────────────────────────────────────────────

// The run's scratch folder: the one it has, or a new one under the first
// scratch root, made with mktemp. Undefined when none can be made.
async function scratchFolderOf($: EngineInterface, run: Run): Promise<string | undefined> {
  const { value: kept } = await $.state.get({ plugin: 'workbench-dev-team', key: 'scratch', id: run.key })
  if (kept && (await $.fs.exists(kept).catch(() => false))) return kept
  const roots = await $.workbench.scratchRoots()
  const root = rootOf(roots)
  if (root === undefined) return undefined
  const made = await $.process.run(['mktemp', '-d', `${root}/${prefixOf(run.type)}.XXXXXX`])
  const folder = made.stdout.trim()
  if (made.exitCode !== 0 || !isDeletable(folder, roots)) return undefined
  await $.state.set({ plugin: 'workbench-dev-team', key: 'scratch', id: run.key }, folder)
  await recordFolder($, [folder], 'add')
  return folder
}

const FOLDERS = { plugin: 'workbench-dev-team', key: 'scratchFolders' } as const

// Adds folders to the record, or takes them out. Two runs can write at once,
// so the write lands only on the version it read, and is tried again when
// another write came first.
async function recordFolder($: EngineInterface, folders: readonly string[], change: 'add' | 'remove'): Promise<void> {
  for (let attempt = 0; attempt < 8; attempt++) {
    const { value = [], version } = await $.state.get(FOLDERS)
    const rest = value.filter(kept => !folders.includes(kept))
    if ((await $.state.set(FOLDERS, change === 'add' ? [...rest, ...folders] : rest, { ifVersion: version })).isSet) return
  }
}

// The end of the session: every folder still recorded is deleted, in one rm,
// when it lies under a scratch root. Each was kept because its run had not
// ended, or a child of its run was live at the run's last turn, and nothing is
// live once the session ends.
// The rm is held to what the end's one short budget leaves, and skipped when
// too little is left. A folder outside every root is never deleted. Only what
// an rm that exited 0 deleted leaves the record: a folder the rm skipped, or
// one an rm that failed or ran out of time may have left, stays recorded.
async function endSession($: EngineInterface, budget: { remainingMs: number }): Promise<void> {
  const { value: folders = [] } = await $.state.get(FOLDERS)
  if (folders.length === 0) return
  const sweep = sweepOf(folders, await $.workbench.scratchRoots(), budget.remainingMs)
  if (sweep === undefined) return
  const removed = await $.process.run(['rm', '-rf', '--', ...sweep.doomed], { timeoutMs: sweep.timeoutMs }).catch(() => undefined)
  if (removed?.exitCode === 0) await recordFolder($, sweep.doomed, 'remove')
}

// The Bash line with a dev-team agent's bare mktemp pointed at its folder, or
// the line as written when it has none, or when anything here fails: a mktemp
// left in $TMPDIR is how the line ran before the mod.
async function withScratch($: EngineInterface, agentId: string | undefined, line: string): Promise<string> {
  if (!line.includes('mktemp')) return line
  try {
    const before = await $.workbench.parseShell(line)
    if (!hasBareMktemp(before)) return line
    const run = await runOf($, agentId)
    if (run === undefined) return line
    const folder = await scratchFolderOf($, run)
    if (folder === undefined) return line
    const pointed = pointMktemp(line, folder)
    if (pointed === undefined) return line
    return readsAsPointed(before, await $.workbench.parseShell(pointed), folder) ? pointed : line
  } catch {
    return line
  }
}

// The end of a turn: the run's scratch folder deleted, unless a child the run
// spawned is still live, and its budget notice reset. A child's end never
// deletes its parent's folder: an ended agent may resume, as Holmes does when
// his background helpers report, and read it again. A folder kept for a live
// child goes at the end of the next turn that finds none. When the agent list
// cannot be read, the folder stays.
async function endRun($: EngineInterface, agentId: string | undefined): Promise<void> {
  const key = agentId ?? ((await $.workbench.callerLane({})) === 'top-level-agent' ? 'run' : undefined)
  if (key === undefined) return
  const { value: folder } = await $.state.get({ plugin: 'workbench-dev-team', key: 'scratch', id: key })
  const agents = folder ? await $.agent.list().catch(() => undefined) : undefined
  if (folder && agents !== undefined && !hasLiveChild(agents, agentId)) {
    if (isDeletable(folder, await $.workbench.scratchRoots())) await $.process.run(['rm', '-rf', '--', folder])
    await $.state.set({ plugin: 'workbench-dev-team', key: 'scratch', id: key }, '')
    await recordFolder($, [folder], 'remove')
  }
  const { value: told } = await $.state.get({ plugin: 'workbench-dev-team', key: 'overBudget', id: key })
  if (told) await $.state.set({ plugin: 'workbench-dev-team', key: 'overBudget', id: key }, false)
}

// ── The context budget ───────────────────────────────────────────────────────

async function measure($: EngineInterface, agentId: string | undefined, usage: TurnUsage | null): Promise<void> {
  const tokens = contextOf(usage)
  if (!isOverBudget(tokens) || tokens === undefined) return
  const run = await runOf($, agentId)
  if (run === undefined) return
  const { value: told } = await $.state.get({ plugin: 'workbench-dev-team', key: 'overBudget', id: run.key })
  if (told) return
  await $.state.set({ plugin: 'workbench-dev-team', key: 'overBudget', id: run.key }, true)
  const notice = budgetNotice(run.type, run.key, tokens)
  $.ui.toast(notice, { timeoutMs: 15000 })
  $.ui.log(notice, { to: 'transcript' })
}

// ── The Index dispatcher ─────────────────────────────────────────────────────

// The Agent call's answer for a Watson Index-mode dispatch: the dispatcher's
// first line, or a refusal. It never falls through to a spawn, which would
// start a run without its pipeline flag.
async function runDispatcher($: EngineInterface, itemId: string, prompt: string) {
  const home = await $.env.get('HOME').catch(() => undefined)
  if (!home) return { deny: dispatchDeny('HOME is not set, so the dispatcher cannot be found') }
  const run = await $.process.run(dispatcherArgv(home, itemId), { timeoutMs: 120_000 }).catch(() => undefined)
  if (run === undefined) return { deny: dispatchDeny('the dispatcher could not run') }
  const outcome = dispatchOutcome(run)
  if ('deny' in outcome) return outcome
  return { result: dispatchResult(outcome.line, prompt), context: [DISPATCH_CONTEXT] }
}

// ── The guards ───────────────────────────────────────────────────────────────

const GUARDED: ReadonlySet<string> = new Set(['Bash', 'Edit', 'Write', 'NotebookEdit'])

const GUARD_FAILED =
  '🛑 Blocked: a call the guards could not judge.\n\nworkbench-dev-team. The commit guard or the review guard failed while reading this call, so it is refused rather than let an unread commit, push, merge, or write through. Report this to the human as a guard defect. Do not try another spelling.'

// The input fields the guards read. The engine types them per tool; these are
// read as unknown, so a field of the wrong type is judged as absent.
type GuardInput = { tool: string; agentId?: string; command?: unknown; file_path?: unknown; notebook_path?: unknown }

// Whether a call comes from a Holmes reviewer, or from anything a reviewer
// spawned: true, false, or undefined when it cannot be told. A top-level
// `--agent` run names its type in CLAUDE_CODE_AGENT, and every loop in it is
// held. A sub-agent's type, and its parents', come from $.agent.list().
async function isReviewer($: EngineInterface, agentId: string | undefined, lane: CallerLane | undefined): Promise<boolean | undefined> {
  if (isReviewerType(await $.env.get('CLAUDE_CODE_AGENT').catch(() => undefined))) return true
  if (lane === 'main' || lane === 'top-level-agent') return false
  if (lane === undefined || agentId === undefined) return undefined
  const agents = await $.agent.list().catch(() => undefined)
  if (agents === undefined) return undefined
  const seen = new Set<string>()
  for (let id: string | undefined = agentId; id !== undefined && !seen.has(id); ) {
    seen.add(id)
    const agent = agents.find(a => a.id === id)
    if (agent === undefined) return undefined
    if (isReviewerType(agent.type)) return true
    id = agent.parentId
  }
  return false
}

// The scratch roots: core's, and $TMPDIR, each a physical directory.
async function scratchRootsOf($: EngineInterface): Promise<string[]> {
  const roots = [...(await $.workbench.scratchRoots().catch(() => []))]
  const tmp = await $.env.get('TMPDIR').catch(() => undefined)
  const real = tmp ? (await $.fs.stat(tmp, { resolve: true }).catch(() => undefined))?.realPath : undefined
  if (real !== undefined && (await $.fs.stat(real).catch(() => undefined))?.kind === 'dir') roots.push(real)
  return roots
}

// The review guard's refusal for a reviewer's call, or undefined.
async function reviewDeny($: EngineInterface, e: GuardInput, parse: ShellParse | undefined): Promise<string | undefined> {
  const cwd = await $.session.cwd().catch(() => undefined)
  const context = { cwd, home: await $.env.get('HOME').catch(() => undefined) }
  let verdict
  if (e.tool === 'Bash') {
    if (parse === undefined) return undefined
    verdict = reviewBash(parse, context)
  } else {
    const raw = e.tool === 'NotebookEdit' ? e.notebook_path : e.file_path
    verdict = reviewEdit(e.tool, typeof raw === 'string' ? raw : '', context)
  }
  const roots = await scratchRootsOf($)
  if ('finding' in verdict) return refusalOf(verdict.finding, roots)
  const disk: Disk = {
    stat: path => $.fs.stat(path, { resolve: true }).then(stat => ({ realPath: stat.realPath }), () => undefined),
    names: dir => $.fs.list(dir).then(entries => entries.map(entry => entry.name), () => undefined),
  }
  const finding = await judgeWrites(verdict.writes, roots, disk)
  return finding === undefined ? undefined : refusalOf(finding, roots)
}

// The guards on one call: the commit guard and the subject check on a Bash line
// in every lane, then the review guard when a reviewer makes the call, or when
// who makes it cannot be told and the call writes outside scratch.
async function guard($: EngineInterface, e: GuardInput): Promise<string | undefined> {
  const lane = await $.workbench.callerLane(e.agentId === undefined ? {} : { agentId: e.agentId }).catch(() => undefined)
  let parse: ShellParse | undefined
  if (e.tool === 'Bash') {
    const line = typeof e.command === 'string' ? e.command : ''
    parse = await $.workbench.parseShell(line)
    const isUnattended = await $.workbench.isUnattended().catch(() => true)
    const refused = commitVerdict(parse, line, { lane, isUnattended }) ?? subjectVerdict(parse)
    if (refused !== undefined) return refused.deny
  }
  const reviewer = await isReviewer($, e.agentId, lane)
  if (reviewer === false) return undefined
  const deny = await reviewDeny($, e, parse)
  if (deny === undefined || reviewer) return deny
  return `${deny}\n\nThe guard could not tell which agent made this call, so it held the call to the reviewer's rule. Report this to the human as a guard defect.`
}

// ── The panes ────────────────────────────────────────────────────────────────

// Both panes only read. The runs pane lists the log folder and runs awk and
// ps. The board pane runs the tick's board mode, which uses the cached token
// only: it never mints, never reads the Keychain, and writes nothing.

const RUNS_COMMAND = 'dev-team-runs'
const BOARD_COMMAND = 'dev-team-board'
const PANE_TITLE = { [RUNS_PANE]: 'Dev-team runs', [BOARD_PANE]: 'The Index board' } as const

const runsAtom = atom({ plugin: 'workbench-dev-team', key: 'runs' } as const, { rows: [] } as RunsView)
const boardAtom = atom({ plugin: 'workbench-dev-team', key: 'board' } as const, EMPTY_BOARD)

// What the panes keep between refreshes in one load of the module: each read
// log's end by name, with the size and mtime it was read at, whether a refresh
// of each pane is under way, and the refresh timer.
type PaneMemory = { ends: Map<string, { stamp: string; end: LogEnd }>; isRunsBusy: boolean; isBoardBusy: boolean; timer?: Timer }

async function logDirOf($: EngineInterface): Promise<string | undefined> {
  const home = await $.env.get('HOME').catch(() => undefined)
  return home ? `${home}/${LOG_DIR}` : undefined
}

const stampOf = (run: { mtimeMs: number; size: number }): string => `${run.mtimeMs}:${run.size}`
const NO_END: LogEnd = { tail: [], refusals: 0 }

// The runs view from the newest logs. Only a log whose size or mtime changed
// since its last read is read again.
async function readRuns($: EngineInterface, memory: PaneMemory): Promise<RunsView> {
  const dir = await logDirOf($)
  if (dir === undefined) return { rows: [], error: 'HOME is not set, so the dispatch logs cannot be found.' }
  const entries = await $.fs.list(dir).catch(() => undefined)
  if (entries === undefined) return { rows: [], error: `There is no dispatch log folder at ${dir}.` }
  const runs = newestRuns(entries)
  if (runs.length === 0) return { rows: [] }
  const changed = runs.filter(run => memory.ends.get(run.name)?.stamp !== stampOf(run))
  if (changed.length > 0) {
    const scan = await $.process.run(scanArgv($.plugin.root, changed.map(run => `${dir}/${run.name}`)), { timeoutMs: 20_000 }).catch(() => undefined)
    // The scan skips a log it cannot open, so a non-zero exit with output is
    // still the ends of the logs it read. No output and a failure is no read.
    if (scan === undefined || (scan.exitCode !== 0 && scan.stdout === '')) return { rows: [], error: 'The dispatch logs could not be read.' }
    const scanned = endsOf(scan.stdout)
    for (const run of changed) {
      const end = scanned.get(`${dir}/${run.name}`)
      if (end === undefined) memory.ends.delete(run.name)
      else memory.ends.set(run.name, { stamp: stampOf(run), end })
    }
  }
  // A changed log the scan could not open was deleted since the listing: its
  // run leaves the pane, and the others stay.
  const read = runs.filter(run => memory.ends.get(run.name)?.stamp === stampOf(run))
  for (const name of memory.ends.keys()) if (!read.some(run => run.name === name)) memory.ends.delete(name)
  const ps = await $.process.run(['ps', '-axo', 'command='], { timeoutMs: 10_000 }).catch(() => undefined)
  if (ps === undefined || ps.exitCode !== 0) return { rows: [], error: 'The process list could not be read, so which runs are live is unknown.' }
  const ends = new Map(read.map(run => [`${dir}/${run.name}`, memory.ends.get(run.name)?.end ?? NO_END]))
  return { rows: rowsOf(dir, read, ends, livePairsOf(ps.stdout), markersOf(entries)) }
}

async function refreshRuns($: EngineInterface, memory: PaneMemory): Promise<void> {
  if (memory.isRunsBusy) return
  memory.isRunsBusy = true
  try {
    const view = await readRuns($, memory)
    await update($, runsAtom, () => view)
  } finally {
    memory.isRunsBusy = false
  }
}

// The escalated items, read from the log folder on every refresh, and the
// board from The Index when the cadence allows. The attempt is recorded before
// the client runs, so no later refresh, and no reload, starts a second one
// inside the cadence.
async function refreshBoard($: EngineInterface, memory: PaneMemory, cadenceMs: number): Promise<void> {
  const dir = await logDirOf($)
  const entries = dir === undefined ? [] : await $.fs.list(dir).catch(() => [])
  const escalated = escalatedOf(markersOf(entries))
  await update($, boardAtom, view => ({ ...view, escalated }))
  if (memory.isBoardBusy) return
  const now = await $.clock.now()
  if (!isDue(await read($, boardAtom), now, cadenceMs)) return
  memory.isBoardBusy = true
  try {
    await update($, boardAtom, view => ({ ...view, attemptedAt: now }))
    const run = await $.process.run(boardArgv($.plugin.root), { timeoutMs: BOARD_TIMEOUT_MS }).catch(() => undefined)
    const outcome = boardOutcome(run)
    await update($, boardAtom, view => afterFetch(view, now, outcome))
  } finally {
    memory.isBoardBusy = false
  }
}

// One refresh of every open pane. With none open, the timer stops.
async function refreshPanes($: EngineInterface, memory: PaneMemory, cadenceMs: number): Promise<void> {
  const open = new Set((await $.ui.panes()).map(pane => pane.id))
  if (!open.has(RUNS_PANE) && !open.has(BOARD_PANE)) {
    memory.timer?.cancel()
    memory.timer = undefined
    return
  }
  await Promise.all([open.has(RUNS_PANE) ? refreshRuns($, memory) : undefined, open.has(BOARD_PANE) ? refreshBoard($, memory, cadenceMs) : undefined])
}

function startRefresh($: EngineInterface, memory: PaneMemory, cadenceMs: number): void {
  memory.timer ??= $.clock.every(RUNS_REFRESH_MS, () => void refreshPanes($, memory, cadenceMs).catch(() => undefined))
}

// Whether this session gets the dev-team rules (mods/session-rules.ts). An
// environment that cannot be read sends them: losing the rules is the worse
// failure, as workbench-core rules for its own.
async function isRulesSession($: EngineInterface): Promise<boolean> {
  return $.env.get('WORKBENCH_SKIP_WARMUP').then(isRulesLane, () => true)
}

export const register: Register = (on, options) => {
  // The rows, read once: the options are fixed for this activation.
  const config = configTextOf(options)

  // The panes. Neither one writes: see refreshRuns and refreshBoard.
  const cadenceMs = cadenceMsOf(options.dispatchCadenceMinutes)
  const memory: PaneMemory = { ends: new Map(), isRunsBusy: false, isBoardBusy: false }

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: RUNS_COMMAND, description: 'Show live and recent dev-team runs from the dispatch logs', immediate: true }).catch(() => undefined)
    await $.command.register({ name: BOARD_COMMAND, description: "Show The Index board's lanes, fetched once per dispatch cadence at most", immediate: true }).catch(() => undefined)
    const open = await $.ui.panes().catch(() => [])
    if (open.some(pane => pane.id === RUNS_PANE || pane.id === BOARD_PANE)) startRefresh($, memory, cadenceMs)
    return next(e)
  })

  on('command.run', async ($, e, next) => {
    const pane = e.command === RUNS_COMMAND ? RUNS_PANE : e.command === BOARD_COMMAND ? BOARD_PANE : undefined
    if (pane === undefined) return next(e)
    await $.ui.open({ id: pane, title: PANE_TITLE[pane] })
    startRefresh($, memory, cadenceMs)
    void refreshPanes($, memory, cadenceMs).catch(() => undefined)
    return { text: `${PANE_TITLE[pane]} pane opened.` }
  }).catch(($, e, next) => (e.command === RUNS_COMMAND || e.command === BOARD_COMMAND ? { text: 'The dev-team pane could not open. Try the command again.' } : next(e)))

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId === RUNS_PANE) return runsTree($.ui.resolve(e), await read($, runsAtom), e.props.scroll.bodyRows)
    if (e.requestId === BOARD_PANE) return boardTree($.ui.resolve(e), await read($, boardAtom), cadenceMs)
    return next(e)
  })

  // The gate fails closed: a dispatch it judges whose brief cannot be checked
  // is refused, and so is one whose gate throws before next is called.
  // workbench-core is a declared dependency, so a check that rejects is a
  // fault, and /orchestrator off is the way past it. The helper rule and the
  // workspace check are refusals too, and each says how it fails below. What
  // follows them (the config, the routing) is not a guard: when it fails, the
  // dispatch goes on unchanged, unrouted and on the agent file's own model,
  // which is how the public type runs without this module.
  on('agent.spawn', async ($, e, next) => {
    // Only the model's own Agent calls are judged, the ones the bash gate sees.
    // A plugin's $.agent.spawn is the plugin's implementation, not a handoff.
    const isModel = next.origin.plugin === 'engine'
    const isGatedCall = isModel && (await gated($, e.parentAgentId))
    if (isGatedCall) {
      const check = await $.workbench.briefCheck(e.prompt).catch(() => undefined)
      if (check === undefined) return { deny: uncheckedDeny() }
      if (!check.isComplete) {
        const slots = await $.workbench.briefSlots().catch(() => [])
        return { deny: denyOf(check.missing, slots) }
      }
    }

    // The helper rule. A spawner the mod cannot name is let through: the
    // review guard still holds every write by anything Holmes spawned.
    let input = e
    if (isModel && isHolmesMode(await spawnerTypeOf($, e.parentAgentId))) {
      const lens = lensSpawnOf(e)
      if ('deny' in lens) return lens
      input = { ...e, subagentType: lens.subagentType }
    }

    // The workspace check. git answering with no branch (not a repository, or
    // a detached HEAD) passes; git that cannot run at all refuses, since the
    // answer is then unknown, and recording a branch in Workdir: passes.
    if (isGatedCall && familyOf(input.subagentType) === 'watson' && modeTypeOf('watson', input.prompt).endsWith(':watson-direct')) {
      const workdir = workdirOf(input.prompt)
      if (workdir !== undefined && !workdir.isRecorded && workdir.path.startsWith('/')) {
        const head = await $.process
          .run(['git', '-C', workdir.path, 'symbolic-ref', '--quiet', '--short', 'HEAD'], { timeoutMs: 10_000 })
          .catch(() => undefined)
        if (head === undefined) return { deny: branchUnreadDeny(workdir.path) }
        const branch = head.stdout.trim()
        if (head.exitCode === 0 && DEFAULT_BRANCHES.includes(branch)) return { deny: branchDeny(workdir.path, branch) }
      }
    }

    // Nothing in this block calls next, so a failure here passes the dispatch
    // on unchanged, and next is called once either way.
    let routed: typeof e | undefined
    let knobs: ReturnType<typeof knobsOf> = {}
    try {
      const family = familyOf(input.subagentType)
      if (family !== undefined) {
        knobs = knobsOf(config, family)
        const subagentType = modeTypeOf(family, input.prompt)
        const configFamily = CONFIG_MODES[subagentType]
        const prompt = configFamily === undefined ? input.prompt : withConfigLine(input.prompt, configLineOf(config, configFamily))
        // A model the caller named is the caller's choice, and stands.
        const model = input.model ?? knobs.model
        routed = { ...input, subagentType, prompt, ...(model === undefined ? {} : { model }) }
      }
    } catch {
      routed = undefined
    }
    const spawned = routed ?? input
    const result = await next(spawned)
    if (result.agentId !== undefined) {
      if (routed !== undefined && knobs.effort !== undefined) {
        await $.state.set({ plugin: 'workbench-dev-team', key: 'effort', id: result.agentId }, knobs.effort)
      }
      if (isDevTeamType(spawned.subagentType)) {
        await $.state.set({ plugin: 'workbench-dev-team', key: 'agentType', id: result.agentId }, spawned.subagentType)
      }
    }
    return result
  }).catch(($, e, next) => (next.called ? next(e) : { deny: uncheckedDeny() }))

  // The dev-team session rules: a shared section in the main loop's system
  // prompt, and context at a sub-agent's start.
  on('prompt.compose', async ($, e, next) => {
    const result = await next(e)
    return (await isRulesSession($)) ? { sections: withRules(result.sections) } : result
  })

  on('classic.SubagentStart', async ($, e, next) => {
    const result = await next(e)
    if (!isRulesSubagent(e.agent_type) || !(await isRulesSession($))) return result
    return { ...result, additionalContext: [...(result.additionalContext ?? []), RULES] }
  })

  // The config line for a top-level run of a mode that reads it. Nothing here
  // calls next, so a failure leaves the prompt as it came.
  on('prompt.submit', async ($, e, next) => {
    let line: string | undefined
    try {
      if ((await $.workbench.callerLane({})) === 'top-level-agent') {
        const family = CONFIG_MODES[(await $.env.get('CLAUDE_CODE_AGENT')) ?? '']
        if (family !== undefined) line = configLineOf(config, family)
      }
    } catch {
      line = undefined
    }
    return next(line === undefined ? e : { ...e, context: [...(e.context ?? []), line] })
  })

  on('turn.step', async function* ($, e, next) {
    let input = e
    if (e.agentId !== undefined) {
      const { value: effort } = await $.state.get({ plugin: 'workbench-dev-team', key: 'effort', id: e.agentId })
      if (effort !== undefined) input = { ...e, effort }
    }
    const result = yield* next(input)
    await measure($, e.agentId, result.usage).catch(() => undefined)
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    await endRun($, e.agentId).catch(() => undefined)
    return result
  })

  // The sweep runs before the engine's own end step, and its failure leaves
  // the folders where they are rather than holding the exit up.
  on('session.end', async ($, e, next) => {
    await endSession($, next.budget).catch(() => undefined)
    return next(e)
  })

  // One tool.call hook, since a plugin registers each event once. A guard that
  // throws refuses the call (fail closed), a scratch rewrite that fails leaves
  // the line as written, and the hint's failure leaves the call as it ran.
  on('tool.call', async ($, e, next) => {
    if (e.tool === 'Bash' || e.tool === 'Edit' || e.tool === 'Write' || e.tool === 'NotebookEdit') {
      const call = e.tool === 'Bash' && typeof e.command === 'string' ? { ...e, command: await withScratch($, e.agentId, e.command) } : e
      const deny = await guard($, call)
      return deny === undefined ? next(call) : { deny }
    }
    if (e.tool !== 'Agent') return next(e)
    const isModel = next.origin.plugin === 'engine'
    let call = e
    if (isModel) {
      // A set agentId is a sub-agent's call, whatever callerLane says, so a
      // sub-agent never reaches the dispatcher. Only a call with no agentId
      // asks the lane, and a lookup that fails there reads as the main session.
      const isMain = e.agentId === undefined && (await $.workbench.callerLane({}).catch(() => 'main' as const)) === 'main'
      if (isMain) {
        const itemId = indexDispatchOf(e.subagent_type, e.prompt)
        if (itemId !== undefined) return runDispatcher($, itemId, e.prompt)
        if (isForcedBackground(e.subagent_type, e.run_in_background)) call = { ...e, run_in_background: true }
      }
    }
    const result = await next(call)
    if (result.deny !== undefined || result.isError || !isModel) return result
    if (typeof e.prompt !== 'string' || !(await gated($, e.agentId))) return result
    const check = await $.workbench.briefCheck(e.prompt).catch(() => undefined)
    const hint = check === undefined ? undefined : hintOf(check, e.prompt)
    return hint === undefined ? result : { ...result, context: [...(result.context ?? []), hint] }
  }).catch(($, e, next) => (next.called || !GUARDED.has(e.tool) ? next(e) : { deny: GUARD_FAILED }))
}

files.hooks/mods/board.ts:
// The board pane's logic, as pure functions. hooks/register.ts holds the hooks;
// hooks/mods/panes.tsx draws the lanes.
//
// The pane reaches The Index only through `bin/dispatch-tick.sh --board`, run
// from this plugin's own folder. That mode uses the tick's cached token only
// (it never mints, never reads the Keychain, and writes nothing), calls the
// three list tools and nothing else, and prints the lanes as JSON. So no token
// or secret ever reaches this module. The pane runs
// it when it opens and then once per dispatch cadence at most, counting every
// attempt, a failed one included.

// The view types live in the type contract, types/index.d.ts.
import type { Board, BoardItem, BoardLane, BoardView } from '../../types'

export const LANES = ['unrefined', 'review', 'development'] as const

export const EMPTY_BOARD: BoardView = { attemptedAt: 0, escalated: [] }

// The dispatch cadence's default, as in .claude-plugin/plugin.json.
export const DEFAULT_CADENCE_MINUTES = 20

// How long a board fetch may take: three list calls of up to 120 s each in the
// tick's own client.
export const BOARD_TIMEOUT_MS = 400_000

// The cadence in milliseconds, from the /config row. A value that is not a
// number of at least one minute reads as the default, so a bad row never
// makes the pane call The Index more often.
export function cadenceMsOf(minutes: unknown): number {
  const value = typeof minutes === 'number' && Number.isFinite(minutes) && minutes >= 1 ? minutes : DEFAULT_CADENCE_MINUTES
  return value * 60_000
}

// Whether the pane may fetch the board now: never fetched, or the last attempt
// started a whole cadence ago.
export const isDue = (view: BoardView, now: number, cadenceMs: number): boolean => view.attemptedAt === 0 || now - view.attemptedAt >= cadenceMs

export const boardArgv = (root: string): string[] => ['bash', `${root}/bin/dispatch-tick.sh`, '--board']

const isObject = (value: unknown): value is Record<string, unknown> => typeof value === 'object' && value !== null && !Array.isArray(value)
const text = (value: unknown): string | null => (typeof value === 'string' ? value : null)

function itemOf(value: unknown): BoardItem | undefined {
  if (!isObject(value) || typeof value.id !== 'number') return undefined
  return {
    id: value.id,
    number: typeof value.number === 'number' ? value.number : null,
    isPr: value.isPr === true,
    repo: text(value.repo),
    title: text(value.title),
    claimedAt: text(value.claimedAt),
  }
}

function laneOf(value: unknown): BoardLane | undefined {
  if (!isObject(value)) return undefined
  if (typeof value.error === 'string') return { error: value.error.slice(0, 300) }
  if (typeof value.limit !== 'number' || !Array.isArray(value.items)) return undefined
  const items = value.items.map(itemOf)
  return items.every(item => item !== undefined) ? { limit: value.limit, items: items as BoardItem[] } : undefined
}

// The board the client printed, or undefined when its output is anything else.
// Only the named fields are kept, each of its own type.
export function boardOf(stdout: string): Board | undefined {
  let parsed: unknown
  try {
    parsed = JSON.parse(stdout)
  } catch {
    return undefined
  }
  if (!isObject(parsed) || !isObject(parsed.lanes)) return undefined
  const lanes = parsed.lanes
  const [unrefined, review, development] = LANES.map(lane => laneOf(lanes[lane]))
  return unrefined && review && development ? { unrefined, review, development } : undefined
}

// What one run of the client means: the board, or why there is none. The
// client prints its reason as the last line on stderr, and never a token.
export function boardOutcome(run: { exitCode: number; stdout: string; stderr: string } | undefined): { board: Board } | { error: string } {
  if (run === undefined) return { error: 'the board client could not run' }
  const board = run.exitCode === 0 ? boardOf(run.stdout) : undefined
  if (board !== undefined) return { board }
  const why = run.stderr.split('\n').findLast(line => line.trim() !== '')?.trim()
  if (run.exitCode === 0) return { error: 'the board client printed something that is not a board' }
  return { error: (why ?? `the board client exited ${run.exitCode}`).slice(0, 300) }
}

// The view after a fetch that started at `startedAt`. A failed fetch keeps the
// last board, so the pane still shows it, with its age.
export function afterFetch(view: BoardView, startedAt: number, outcome: { board: Board } | { error: string }): BoardView {
  if ('board' in outcome) return { attemptedAt: startedAt, board: outcome.board, boardAt: startedAt, escalated: view.escalated }
  const { board, boardAt } = view
  return { attemptedAt: startedAt, ...(board ? { board, boardAt } : {}), error: outcome.error, escalated: view.escalated }
}

// "watson item 42" for each escalated pair "watson-42".
export const escalatedOf = (markers: readonly string[]): string[] =>
  markers.map(pair => {
    const dash = pair.lastIndexOf('-')
    return `${pair.slice(0, dash)} item ${pair.slice(dash + 1)}`
  })

files.hooks/mods/budget.ts:
// Each dev-team agent's working-context budget, as pure functions.
// hooks/register.ts measures every model request of a dev-team agent's loop in
// turn.step, and notifies the human once when a request passes the budget. It
// stops nothing: the agents' rule is to finish the work and say what made it
// expensive, never to buy the budget with the work.

import type { TurnUsage } from 'claude-code'

// The budget every dev-team agent's prose states: about 250k tokens of working
// context.
export const BUDGET_TOKENS = 250_000

// A request's working context: every input token it was answered over, cached
// or not. Undefined when the request carried no usage.
export const contextOf = (usage: TurnUsage | null | undefined): number | undefined =>
  usage == null ? undefined : usage.input_tokens + usage.cache_read_input_tokens + usage.cache_creation_input_tokens

export const isOverBudget = (tokens: number | undefined): boolean => tokens !== undefined && tokens > BUDGET_TOKENS

// The notice, one line: which agent, how far past, and that nothing stopped.
export function budgetNotice(type: string, id: string, tokens: number): string {
  const k = (n: number) => `${Math.round(n / 1000)}k`
  return `📏 workbench-dev-team: ${type.split(':').pop()} (${id}) passed its ${k(BUDGET_TOKENS)}-token working-context budget, at ${k(tokens)} in its latest request. Nothing was stopped.`
}

files.hooks/mods/commit-guard.ts:
// The commit guard, as pure functions over workbench-core's reading of a Bash
// line ($.workbench.parseShell). hooks/register.ts calls them on every Bash
// call, in every lane. It refuses what the permissions.ask rules cannot cover,
// and is silent on everything else.
//
// The approval is a "Commit it" pick in `AskUserQuestion`, once the human says
// their review is done. Claude Code's own prompt is the mechanical backstop.
// /workbench-dev-team:setup installs the ask rules git commit *, git push *,
// git * commit *, git * push *, git * commit, git * push, gh * pr merge *,
// gh * pr merge, and gh api *pulls/*/merge*, beside workbench-core's own
// gh pr merge:*. This guard does not ask and does not approve. It catches honest
// mistakes. It is not a security boundary: a script file, an interpreter, or a
// shell alias gets past it, and past the ask rules too. Review is the real gate.
//
// ACCEPTED LIMITS (Mike, 2026-10-07: the guards stay mistake-catchers, and
// these gaps are accepted rather than chased). The guard reads the words of a
// line, so a change it cannot see in them is out of scope: a value-only change
// such as PATH=, HOME= or XDG_CONFIG_HOME= before git; git -C into a
// repository whose own config is hostile; an arithmetic assignment such as
// $((X=1)); a bash alias defined on the same line; a git alias in a config
// file; a script file or a file passed to make; a command that code builds at
// run time, such as python joining "git" and "push"; and a GraphQL mutation
// held in a variable or a file (`-f query="$Q"`, `--input file`).
//
// It refuses, in this order:
//   1. A push that forces or deletes, in every lane: --force, --force-with-lease,
//      --mirror, --delete, --prune (and their prefixes), -f or -d in a short
//      cluster, a refspec that starts with + or :, or a -c that makes a remote
//      mirror or names its push refspec.
//   2. A pull request merge from a sub-agent, from a top-level `--agent` run
//      such as the pipeline, or from any turn nobody attends: gh pr merge in any
//      spelling, or gh api on pulls/<n>/merge. Holmes and Watson never merge.
//   3. A commit or push from a sub-agent. A sub-agent hands its work back
//      uncommitted. The scheduled pipeline commits from its top-level
//      `claude -p --agent` loop, which is not a sub-agent.
//   4. A commit, push, or merge the ask rules cannot see, in every lane: behind
//      a wrapper the harness does not strip before it matches (env, sudo,
//      xargs, caffeinate, ...), a NAME=value assignment, a `bash -c` or `eval`
//      script, a substitution, or a heredoc fed to a shell;
//      a git or gh named by a path or in another case; an escaped word; a
//      subcommand a `-c alias.<name>` supplies; or a subcommand, or a global
//      option word before it, built at run time from a substitution or a
//      variable (`git "$(echo commit)"`, `git $x`, `gh pr $(echo merge)`). The
//      guard cannot tell which subcommand that is, so it counts as any of
//      them. An option's value (`-C "$D"`, `--git-dir=$D`, `-R"$R"`) decides
//      no subcommand. A gh api endpoint built at run time counts as a merge
//      when the method is PUT or built, or a built word stands where a flag
//      could (the REST merge takes a PUT), and a gh api line whose fields
//      name the GraphQL mergePullRequest or enablePullRequestAutoMerge
//      mutation counts as a merge whatever its endpoint and method.
//   5. In a sub-agent, or in a run nobody attends (an attended top-level
//      `--agent` run is neither): a line whose command name the
//      reader cannot place (a wrapper option it cannot read) or that is built
//      at run time from a substitution or a variable (`"$CMD" x`,
//      `g$(echo it) push`), whatever the line names. Mike accepted the cost on
//      2026-10-07: a rare `$CMD …` line refused there. A plain `"$NAME/…"`
//      before a literal path names its program, so it is not refused. Since
//      workbench-core 4e83554, core's guards refuse each of these lines first,
//      in every lane. This rule stays as dev-team's own check in the lanes no
//      human watches. A substitution in front of a literal path (`$(…)x/y`)
//      is refused here through the reader's own `expansion` unknown, since
//      workbench-core 47a5e27. So is any line with any unknown at all
//      (HIDES_NAME): each can leave a command with no name to read, and the
//      cost is a rare line refused, such as one whose $'…' holds an escape the
//      reader does not decode (a Unicode or control escape).
//
// THE FOURTH RULE IS KEPT. workbench-core's commit approval gate reads past
// every hidden form above, but only for a commit or push in the main loop of an
// attended session. It stands aside for a sub-agent, a top-level `--agent` run,
// a session nobody sits at, and a turn a schedule opened, and it never looks at
// a merge. In those places a hidden form draws no prompt from the ask rules and
// no question from core, so this rule is the only thing that stops it.
//
// LANES. The lane is $.workbench.callerLane's: `main`, `sub-agent`, or
// `top-level-agent` (a `claude -p --agent` run, the pipeline among them). A
// lane the noun cannot give is read as a sub-agent, the side that refuses. The
// merge rule also reads $.workbench.isUnattended, and an unknown answer there is
// read as unattended.
//
// READING. Each rule reads the statements parseShell returns, never the text of
// the line, so `git commit -m "load env"`, `grep "git push" notes.md`, and a
// heredoc data file that quotes `git push origin` are not refused. Text is
// read in three places only, each where a command may be hidden from the
// statements:
//   - A line parseShell could not read whole (any unknown), or with a wrapper
//     it could not place, that names commit, push, or merge anywhere: rule 4
//     in every lane, and rule 1 when the text reads as a forced push.
//   - Code a program runs from its own words or heredoc: the arguments of
//     anything that is not a plain reader (python -c, awk system(), sed's e
//     command, a runner the shell reader does not list, `rg --pre`), a git -c
//     value, `git grep -O`, and a `-c alias.<name>=!…` shell alias. A mention of
//     git commit, push, or gh pr merge there counts as that command behind a
//     wrapper: rules 1 to 4. A mention that is only a quote is refused too,
//     on purpose: a `node -e` that counts the string 'git push' reads the same
//     as one that runs it through child_process, and the guard cannot show a
//     script cannot run git. Node reaches child_process with no fixed word in
//     the text (`require(['child', 'process'].join('_'))`), so no word list
//     proves its absence. This is the cost of a mistake-catcher that does not
//     read code (workbench-core report, 2026-10-09).
//   - Text a plain reader handles (echo, cat, a heredoc data file) on a line
//     that also runs a program that could read it back, such as
//     `echo git push > x.sh; bash x.sh`: rules 1 to 3, not rule 4.
// In the second and third, a whole line of a comment (# or //) is skipped, so
// a script whose comment says "git commit or push" is not refused. The first
// reads the raw line, comments included.

import type { EngineInterface } from 'claude-code'

type Workbench = EngineInterface['workbench']
export type ShellParse = Awaited<ReturnType<Workbench['parseShell']>>
export type Statement = ShellParse['statements'][number]
export type CallerLane = Awaited<ReturnType<Workbench['callerLane']>>

// Who runs the line. lane is undefined when callerLane could not answer.
export type Caller = { lane: CallerLane | undefined; isUnattended: boolean }

type Op = 'commit' | 'push' | 'merge'

// The guard's verdict: the refusal the model reads, or undefined to pass.
export type Refusal = { deny: string }

// What a line runs, as the rules weigh it.
type Found = {
  // Commits, pushes and merges the rules 1 to 3 weigh.
  ops: Set<Op>
  // A push that forces or deletes.
  isForce: boolean
  // An op the ask rules cannot see (rule 4).
  isHidden: boolean
}

// The text match of the bash guard before this one (tests/oracle/), kept for
// the text the statements cannot show. A character that cannot be part of a
// word, then git and commit or push, or gh and pr merge or the API merge
// endpoint, within one command.
const W = '[^A-Za-z0-9_.-]'
const SEG = '[^;&|\\n]'
const GIT_OP = `git${W}(?:${SEG}*[^A-Za-z0-9_-])?(commit|push)(?:$|[^A-Za-z0-9_-])`
const MERGE_OP = `gh${W}(?:${SEG}*[^A-Za-z0-9_-])?(?:pr\\s+merge|api${W}${SEG}*pulls/[^\\s/]+/merge)(?:$|[^A-Za-z0-9_/-])`
const MENTION = new RegExp(`(?:^|${W})(?:${GIT_OP}|${MERGE_OP})`, 'im')
const FORCE_TEXT = new RegExp(
  `(?:^|${W})git${W}(?:${SEG}*[^A-Za-z0-9_-])?push${SEG}*\\s(?:--(?:forc|m|de|pru)|-[A-Za-z0-9]*[fd]|[+:]\\S)`,
  'im',
)
// Any of the three words, for a line the reader could not read whole.
const LOOSE = /commit|push|merge/i

// Programs that never run code from their own words: what they are handed is
// data. Text in their words is read only beside a program that could run it.
const READERS: ReadonlySet<string> = new Set([
  'echo', 'printf', 'cat', 'head', 'tail', 'wc', 'ls', 'grep', 'egrep', 'fgrep', 'rg', 'jq', 'cd', 'pwd', 'true',
  'false', 'test', '[', '[[', '((', ':', 'printenv', 'basename', 'dirname', 'realpath', 'readlink', 'stat', 'file',
  'which', 'type', 'command', 'diff', 'cmp', 'comm', 'cut', 'tr', 'sort', 'uniq', 'column', 'nl', 'tee', 'mkdir',
  'touch', 'rm', 'rmdir', 'mv', 'cp', 'ln', 'chmod', 'date', 'sleep', 'export', 'local', 'declare', 'readonly',
  'unset', 'set',
])

// The wrappers Claude Code strips before it matches an ask rule, so a commit
// behind one still prompts.
const ASK_STRIPPED: ReadonlySet<string> = new Set(['timeout', 'time', 'nice', 'nohup', 'stdbuf', 'command', 'builtin', 'noglob'])

// A command name the shell builds at run time: a brace (`{git,}`), a glob, or
// zsh's `=name` path expansion. Which program runs is not written.
const BUILT_NAME = /[{}*?[\]]|^=/

// Whole-line comments, dropped before text is matched.
const withoutComments = (text: string): string =>
  text
    .split('\n')
    .filter(line => !/^\s*(?:#|\/\/)/.test(line))
    .join('\n')

const opsIn = (text: string): Op[] => {
  const ops: Op[] = []
  const match = new RegExp(MENTION.source, 'gim')
  for (const m of text.matchAll(match)) {
    // GIT_OP captures commit or push. MERGE_OP captures nothing.
    ops.push(m[1] === undefined ? 'merge' : (m[1].toLowerCase() as Op))
  }
  return ops
}

// A git option word that sets configuration: `-c key=value` or `-ckey=value`.
function configOf(args: readonly string[], end: number): { key: string; value: string }[] {
  const config: { key: string; value: string }[] = []
  for (let i = 0; i < end; i++) {
    const arg = args[i] ?? ''
    const pair = arg === '-c' ? args[++i] : arg.startsWith('-c') ? arg.slice(2) : undefined
    if (pair === undefined) continue
    const at = pair.indexOf('=')
    config.push({ key: (at < 0 ? pair : pair.slice(0, at)).toLowerCase(), value: at < 0 ? '' : pair.slice(at + 1) })
  }
  return config
}

// A word the shell builds when the line runs: the reader's `$_` stands where a
// substitution stood, and a `$` left in a word is an expansion.
const isBuilt = (word: string): boolean => word.includes('$')

// git's and gh's global options whose value is the next word. A value built at
// run time cannot change which subcommand runs; the option word itself can.
const GLOBAL_VALUES: ReadonlySet<string> = new Set([
  '-C', '-c', '--git-dir', '--work-tree', '--namespace', '--super-prefix', '--config-env', '--exec-path', '-R', '--repo',
])

// A global option word that carries its own value, `--git-dir=$D`, `-C$D` or
// `-R"$R"`: the value decides no subcommand.
const carriesValue = (arg: string): boolean =>
  [...GLOBAL_VALUES].some(o => (o.startsWith('--') ? arg.startsWith(`${o}=`) : arg.startsWith(o) && arg.length > o.length))

// Whether a word that decides which subcommand runs is built at run time: an
// option word before the subcommand (never a value of one, separate, after
// `=` or attached), or the subcommand itself.
function decidesBuilt(s: Statement): boolean {
  const at = s.subcommandAt
  const end = at < 0 ? s.args.length : Math.min(s.args.length, at + 1)
  for (let i = 0; i < end; i++) {
    const arg = s.args[i] ?? ''
    if (i < at && GLOBAL_VALUES.has(arg)) {
      i++
      continue
    }
    if (i < at && carriesValue(arg)) continue
    if (isBuilt(arg)) return true
  }
  return false
}

// gh api's options that take the next word as their value, so the endpoint is
// the first word that is neither an option nor such a value.
const GH_API_VALUES: ReadonlySet<string> = new Set([
  '-f', '--raw-field', '-F', '--field', '-H', '--header', '-X', '--method', '--input', '-q', '--jq', '-t', '--template',
  '--cache', '-p', '--preview', '--hostname',
])

// A gh api call's words as gh reads them (pflag, which takes no cut of a long
// flag): every method value, and the words in endpoint position. A method is
// `-X PUT`, `-XPUT`, `-X=PUT`, `--method PUT` or `--method=PUT`, and a short
// cluster that ends in X (`-iX PUT`) takes the next word, as pflag gives it.
// Every value is kept, since a later one wins and the guard reads them all.
// gh api takes one endpoint, so a second word in that position is a flag the
// shell built (`gh api $M repos/$X` with M=-XPUT).
function apiWordsOf(rest: readonly string[]): { methods: string[]; positionals: string[] } {
  const methods: string[] = []
  const positionals: string[] = []
  for (let i = 0; i < rest.length; i++) {
    const arg = rest[i] ?? ''
    if (arg === '--') {
      positionals.push(...rest.slice(i + 1))
      break
    }
    const cluster = /^-[A-Za-z]*X(.*)$/.exec(arg)
    if (arg === '--method') methods.push(rest[++i] ?? '')
    else if (arg.startsWith('--method=')) methods.push(arg.slice('--method='.length))
    else if (cluster && !arg.startsWith('--')) methods.push(cluster[1] === '' ? (rest[++i] ?? '') : (cluster[1] ?? '').replace(/^=/, ''))
    else if (GH_API_VALUES.has(arg)) i++
    else if (!arg.startsWith('-')) positionals.push(arg)
  }
  return { methods, positionals }
}

// Whether a gh api call could merge a pull request through an endpoint built
// at run time. The REST merge endpoint takes a PUT. gh sends GET, or POST with
// fields, unless the method says otherwise. So with a PUT, a method built at
// run time, or a built word where a flag could stand, any built endpoint
// counts as a merge, since the guard cannot know where it points (fail
// closed). A GraphQL merge goes over POST and is read from the fields
// (MERGE_MUTATION), and a literal pulls/<n>/merge endpoint is matched as
// written, whatever the method.
function builtMerge(rest: readonly string[]): boolean {
  const { methods, positionals } = apiWordsOf(rest)
  if (!positionals.some(isBuilt)) return false
  const isBuiltFlag = positionals.length > 1
  return isBuiltFlag || methods.some(m => isBuilt(m) || m.toUpperCase() === 'PUT')
}

// The GraphQL mutations that merge a pull request, or set it to merge.
const MERGE_MUTATION = /mergePullRequest|enablePullRequestAutoMerge/i

// Whether a push's own words force or delete.
const isForceArg = (arg: string): boolean => /^--(?:forc|m|de|pru)/i.test(arg) || /^-[A-Za-z0-9]*[fd]/.test(arg) || /^[+:]\S/.test(arg)

// What one git or gh statement runs, read from its words.
type Read = { ops: Op[]; isForce: boolean; isHidden: boolean; code: string[]; isUnread: boolean }

function readGit(s: Statement): Read {
  const read: Read = { ops: [], isForce: false, isHidden: false, code: [], isUnread: false }
  const args = s.args
  if (s.name === 'git-commit' || s.name === 'git-push') {
    read.ops.push(s.name === 'git-commit' ? 'commit' : 'push')
    read.isForce = s.name === 'git-push' && args.some(isForceArg)
    return read
  }
  const at = s.subcommandAt
  const config = configOf(args, at < 0 ? args.length : at)
  read.code.push(...config.map(c => c.value))
  // A subcommand built at run time, or configuration whose key is, could be
  // commit or push: read as unread, every op and hidden.
  if (decidesBuilt(s) || config.some(c => isBuilt(c.key))) read.isUnread = true
  if (config.some(c => /^remote\..*\.(?:mirror|push)$/.test(c.key))) read.isForce = true
  if (args.some(arg => arg.startsWith('--config-env'))) read.isUnread = true
  if (at < 0) {
    // Words xargs or parallel add could be the subcommand.
    if (s.wrappers.includes('xargs')) read.isUnread = true
    return read
  }
  let sub = (args[at] ?? '').toLowerCase()
  let rest = args.slice(at + 1)
  const alias = config.find(c => c.key === `alias.${sub}`)
  if (alias !== undefined) {
    read.isHidden = true
    if (isBuilt(alias.value)) read.isUnread = true
    if (alias.value.trimStart().startsWith('!')) {
      // A shell alias: its text is a script the reader was never handed.
      read.code.push(alias.value)
      return read
    }
    const words = alias.value.trim().split(/\s+/)
    sub = (words[0] ?? '').toLowerCase()
    rest = [...words.slice(1), ...rest]
  }
  // git grep -O runs its value as a program on the matched files.
  if (sub === 'grep' && rest.some(arg => arg.startsWith('-O') || arg.startsWith('--open-files'))) {
    read.code.push(...rest.map(arg => arg.replace(/^(?:-O|--open-files[a-z-]*=?)/, ' ')))
  }
  if (sub === 'commit' || sub === 'push') read.ops.push(sub)
  if (sub === 'push' && rest.some(isForceArg)) read.isForce = true
  return read
}

function readGh(s: Statement): Read {
  const read: Read = { ops: [], isForce: false, isHidden: false, code: [], isUnread: false }
  const at = s.subcommandAt
  if (decidesBuilt(s)) read.isUnread = true
  if (at < 0) return read
  const sub = (s.args[at] ?? '').toLowerCase()
  const rest = s.args.slice(at + 1)
  // `gh pr $(echo merge)`: the word after pr is the pr subcommand.
  if (sub === 'pr' && isBuilt(rest[0] ?? '')) read.isUnread = true
  if (sub === 'pr' && rest.some(arg => arg.toLowerCase() === 'merge')) read.ops.push('merge')
  const isLiteralMerge = sub === 'api' && rest.some(arg => /pulls\/[^\s/]+\/merge(?![A-Za-z0-9_/-])/i.test(arg))
  // A GraphQL merge, named in a field or a heredoc fed to --input, over any
  // endpoint and method. The ask rules match no such line.
  if (sub === 'api' && [...rest, ...s.heredocs.map(h => h.body)].some(word => MERGE_MUTATION.test(word))) {
    read.ops.push('merge')
    read.isHidden = true
  }
  if (isLiteralMerge) read.ops.push('merge')
  // A built endpoint the ask rule's pulls/*/merge pattern cannot see.
  if (sub === 'api' && !isLiteralMerge && builtMerge(rest)) {
    read.ops.push('merge')
    read.isHidden = true
  }
  return read
}

// Whether the ask rules would see this git or gh statement as written: a plain
// name in command position, with nothing in front of it but a wrapper the
// harness strips.
function isPlain(s: Statement): boolean {
  const named = s.words[s.nameAt] ?? ''
  const escapedAt = new Set(s.escaped)
  const lastRead = s.nameAt + 1 + Math.max(s.subcommandAt, 0)
  for (let i = s.nameAt; i <= lastRead; i++) if (escapedAt.has(i)) return false
  return s.assignments.length === 0 && s.wrappers.every(w => ASK_STRIPPED.has(w)) && s.source === 'line' && s.depth === 0 && named === s.name
}

// Everything the guard can say about a line: the ops it runs and how they are
// written, from the statements and from the text they cannot show.
export function findOps(parse: ShellParse, line: string): Found {
  const found: Found = { ops: new Set(), isForce: false, isHidden: false }
  const add = (ops: Iterable<Op>, isHidden: boolean) => {
    for (const op of ops) {
      found.ops.add(op)
      if (isHidden) found.isHidden = true
    }
  }
  const all: Op[] = ['commit', 'push', 'merge']

  // A line the reader could not read whole may hide any of them.
  const isUnread = parse.unknowns.length > 0 || parse.statements.some(s => !s.isPlaced)
  if (isUnread && LOOSE.test(line)) {
    add(all.filter(op => new RegExp(op, 'i').test(line)), true)
    if (FORCE_TEXT.test(line.replace(/\\\n/g, '').replace(/["'\\]/g, ''))) found.isForce = true
  }

  // Text a reader handles, and whether anything on the line could run it.
  const readerText: string[] = []
  let hasRunner = false
  for (const s of parse.statements) {
    const heredocs = s.heredocs.filter(h => !h.feedsShell).map(h => h.body)
    const code = (texts: readonly string[]) => {
      const text = withoutComments(texts.join('\n'))
      add(opsIn(text), true)
      if (FORCE_TEXT.test(text)) found.isForce = true
    }
    if (s.nameAt < 0) {
      readerText.push(...s.assignments, ...heredocs)
      continue
    }
    if (s.name === 'git' || s.name === 'git-commit' || s.name === 'git-push' || s.name === 'gh') {
      const read = s.name === 'gh' ? readGh(s) : readGit(s)
      add(read.ops, read.isHidden || !isPlain(s))
      if (read.isForce) found.isForce = true
      if (read.isUnread) add(all, true)
      if (read.code.length > 0) {
        hasRunner = true
        code(read.code)
      }
      readerText.push(...s.assignments, ...heredocs)
      continue
    }
    if (BUILT_NAME.test(s.name) || s.escaped.includes(s.nameAt)) {
      // The program is not written, so it may be git or gh itself.
      hasRunner = true
      code([s.words.slice(s.nameAt).join(' '), ...heredocs])
      if (LOOSE.test(s.words.join(' '))) add(all.filter(op => new RegExp(op, 'i').test(s.words.join(' '))), true)
      continue
    }
    const isReader = READERS.has(s.name) && !(s.name === 'rg' && s.args.some(arg => arg.startsWith('--pre')))
    if (isReader) {
      readerText.push(...s.args, ...s.assignments, ...heredocs)
    } else {
      hasRunner = true
      code([...s.args, ...heredocs])
      readerText.push(...s.assignments)
    }
  }
  if (hasRunner) {
    const text = withoutComments(readerText.join('\n'))
    add(opsIn(text), false)
    if (FORCE_TEXT.test(text)) found.isForce = true
  }
  return found
}

const READS =
  'A command that only reads or quotes these words, such as git log --grep, a grep for them, or a heredoc of notes, is not refused here. The code of a program such as node -e or python3 -c is refused when it names them, even in a quote, because the guard cannot tell a quote there from a call. Read or count that text with grep or the Read tool. If any other read was refused, report it as a guard defect, and use the Read tool for the file meanwhile.'

const refusal = (line: string, why: string): Refusal => ({ deny: `🛑 Blocked: ${line}\n\nCommit guard (workbench-dev-team). ${why}` })

export const FORCE_REFUSAL = refusal(
  'a push that forces or deletes.',
  'Pushes that force or delete remote refs are refused outright, and no approval changes that. Push without the force or delete, or ask the human to do it.',
)

export const MERGE_REFUSAL = refusal(
  'a sub-agent or the pipeline does not merge a pull request.',
  `Merging is the human's own step, after review. Report that the pull request is ready to merge, and stop. Do not look for another route to a merge. ${READS}`,
)

export const SUBAGENT_REFUSAL = refusal(
  'a sub-agent does not commit or push.',
  `Leave the working tree uncommitted. Report the diff and a proposed commit message to the session that dispatched you. Do not ask to commit. Do not look for another route to a commit or push. ${READS}`,
)

export const PLAIN_REFUSAL = refusal(
  'run the commit, push, or merge as a plain line, so you are asked.',
  'The permission rules that prompt the human match a plain git or gh line, and they miss one behind a wrapper such as env or sudo, a leading NAME=value, bash -c, eval, a substitution, a path, an escape, or an alias, and one inside a program or a line the guard cannot read. Run it as git commit …, git push …, or gh pr merge …, with git -C <dir> for a directory and git -c <key>=<value> for configuration. Drop a variable prefix such as HUSKY=0. If the line only quotes these words in the code of a program such as node -e, the guard cannot tell that from a call either. Read or count that text with grep or the Read tool.',
)

export const BUILT_REFUSAL = refusal(
  'a command name the guard cannot read, from a sub-agent or an unattended run.',
  'The command this line runs is named by a variable or a substitution, or the guard cannot read the whole line: a wrapper option it cannot place, a quote, substitution, heredoc, array or case it cannot close, an escape it cannot decode, a script piped into a shell, or scripts nested past four levels. So the guard cannot tell whether it commits, pushes, or merges. Name the program in plain words, such as python3 script.py rather than "$PY" script.py, and write the line so every quote, substitution, heredoc, array and case closes plainly. Do not look for another spelling.',
)

export const FAILED_REFUSAL = refusal(
  'a call the commit guard could not judge.',
  'The guard failed while reading this command, so it refuses it rather than let a commit, push, or merge through unread. Report this to the human as a guard defect. Do not try another spelling.',
)

// Whether any statement's command name is unplaced or built at run time, or
// may be misread, as parseShell reads it. Its `expansion` unknown covers a `$`
// or a backtick anywhere in a command word, except a plain `"$NAME/…"` or
// `"${NAME}/…"` in double quotes before a literal path, whose last path part
// names the program. Since workbench-core 47a5e27 that includes a
// substitution before a path, quoted or not (`$(…)x/y`, `$((…))x/y`), whose
// output only the run decides.
//
// HIDES_NAME holds every unknown the reader can set, because each can leave a
// command the shell runs with no name to read:
//   quote         the reader and the shell can disagree on where a quote
//                 ends: zsh closes the quote in `echo $[ "1 ]; $x$y` and
//                 runs `$x$y`, which the reader reads as quoted text
//   substitution  likewise for a `$(( … ))` or `$( … )` the reader reads as
//                 unclosed
//   heredoc       a delimiter whose $'…' part holds an escape the reader keeps
//                 undecoded, so it reads the lines after the shell's
//                 terminator as body (a plain `<<$'EOF'` is decoded since
//                 workbench-core 159f51a)
//   escape        a $'…' escape the reader does not decode (a Unicode or
//                 control escape), which may spell any name, git included
//   wrapper       a wrapper option the reader cannot place
//   expansion     a name built from a variable or a substitution
//   stdin         a script piped or fed into a shell (`curl … | sh`)
//   depth         scripts nested past four levels, which are not read
//   compound      an array or a case still open where the script ends, where
//                 the reader cannot tell where it was meant to end
// The record is keyed by core's unknown type, so tsc fails when core adds an
// unknown this list does not hold. tests/shipped-lines.mjs reads the list, so
// every shipped shell block is held to it too.
const EVERY_UNKNOWN: Record<ShellParse['unknowns'][number], true> = {
  quote: true, substitution: true, heredoc: true, escape: true, wrapper: true, expansion: true, stdin: true, depth: true, compound: true,
}
export const HIDES_NAME = Object.keys(EVERY_UNKNOWN) as readonly ShellParse['unknowns'][number][]
const hasBuiltName = (parse: ShellParse): boolean =>
  parse.unknowns.some(u => HIDES_NAME.includes(u)) || parse.statements.some(s => !s.isPlaced)

// The verdict on one Bash line, in the order of the header's rules.
export function commitVerdict(parse: ShellParse, line: string, caller: Caller): Refusal | undefined {
  const found = findOps(parse, line)
  // A sub-agent (or a lane callerLane cannot give), or a run nobody attends.
  const isUnwatched = caller.lane === 'sub-agent' || caller.lane === undefined || caller.isUnattended
  if (found.isForce) return FORCE_REFUSAL
  if (found.ops.has('merge') && (caller.lane !== 'main' || caller.isUnattended)) return MERGE_REFUSAL
  const writes = found.ops.has('commit') || found.ops.has('push')
  if (writes && caller.lane !== 'main' && caller.lane !== 'top-level-agent') return SUBAGENT_REFUSAL
  if (found.ops.size > 0 && found.isHidden) return PLAIN_REFUSAL
  if (isUnwatched && hasBuiltName(parse)) return BUILT_REFUSAL
  return undefined
}

